<?php
require_once '../../config/config.php';
require_once '../../config/database.php';
require_once '../../includes/access.php';
access_require_roles(array('Student'));
$conn->set_charset('utf8mb4');
function portal_student_e($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$student_id = access_student_id(); $student = array(); $attendance = array(); $homework = array(); $announcements = array(); $holidays = array();
$stmt = $conn->prepare('SELECT s.*, c.class_name, sec.section_name FROM students s JOIN classes c ON c.id=s.class_id JOIN sections sec ON sec.id=s.section_id WHERE s.id=? AND s.status=1'); $stmt->bind_param('i',$student_id); $stmt->execute(); $student=$stmt->get_result()->fetch_assoc(); $stmt->close();
$stmt = $conn->prepare('SELECT attendance_date,status,remarks FROM student_attendance WHERE student_id=? ORDER BY attendance_date DESC LIMIT 60'); $stmt->bind_param('i',$student_id); $stmt->execute(); $q=$stmt->get_result(); while($x=$q->fetch_assoc())$attendance[]=$x; $stmt->close();
if ($student) {
    $stmt=$conn->prepare("SELECT h.title,h.description,h.due_date,s.subject_name FROM portal_homework h LEFT JOIN subjects s ON s.id=h.subject_id WHERE h.class_id=? AND h.status=1 ORDER BY h.due_date DESC LIMIT 30"); $stmt->bind_param('i',$student['class_id']); $stmt->execute(); $q=$stmt->get_result(); while($x=$q->fetch_assoc())$homework[]=$x; $stmt->close();
}
$q=$conn->query("SELECT title,body,publish_date FROM portal_announcements WHERE status=1 AND audience IN ('All','Students') AND publish_date<=CURDATE() ORDER BY publish_date DESC LIMIT 20"); while($q&&($x=$q->fetch_assoc()))$announcements[]=$x;
$q=$conn->query("SELECT holiday_name,holiday_date FROM portal_holidays WHERE status=1 AND holiday_date>=CURDATE() ORDER BY holiday_date LIMIT 20"); while($q&&($x=$q->fetch_assoc()))$holidays[]=$x;
?>
<?php include '../../includes/header.php'; ?><?php include '../../includes/navbar.php'; ?><?php include '../../includes/sidebar.php'; ?>
<div class="content-wrapper"><section class="content-header"><div class="container-fluid"><h1><i class="fas fa-user-graduate"></i> Student Portal</h1></div></section><section class="content"><div class="container-fluid">
<div class="alert alert-primary"><h4><?=portal_student_e($student['student_name']??'Student')?></h4><p class="mb-0"><?=portal_student_e(($student['class_name']??'').' - Section '.($student['section_name']??''))?> | Admission No: <?=portal_student_e($student['admission_no']??'')?></p></div>
<div class="row"><div class="col-md-6"><div class="card"><div class="card-header bg-success text-white">My Report Cards</div><div class="card-body"><a class="btn btn-primary" href="../results/report_card.php?student_id=<?=$student_id?>&class_id=<?=(int)($student['class_id']??0)?>&section_id=<?=(int)($student['section_id']??0)?>">View My Report Card</a></div></div><div class="card"><div class="card-header bg-info text-white">My Attendance</div><div class="card-body p-0"><table class="table table-sm mb-0"><tr><th>Date</th><th>Status</th><th>Remarks</th></tr><?php foreach($attendance as $x):?><tr><td><?=portal_student_e($x['attendance_date'])?></td><td><?=portal_student_e($x['status'])?></td><td><?=portal_student_e($x['remarks'])?></td></tr><?php endforeach;?><?php if(!$attendance):?><tr><td colspan="3" class="text-muted text-center">No attendance records.</td></tr><?php endif;?></table></div></div></div>
<div class="col-md-6"><div class="card"><div class="card-header bg-warning">Announcements & Notices</div><div class="card-body"><?php foreach($announcements as $x):?><article class="border-bottom pb-2 mb-2"><strong><?=portal_student_e($x['title'])?></strong><small class="d-block text-muted"><?=portal_student_e($x['publish_date'])?></small><p><?=nl2br(portal_student_e($x['body']))?></p></article><?php endforeach;?><?php if(!$announcements):?><p class="text-muted">No announcements.</p><?php endif;?></div></div><div class="card"><div class="card-header bg-secondary text-white">Holidays</div><div class="card-body"><ul><?php foreach($holidays as $x):?><li><?=portal_student_e($x['holiday_date'].' - '.$x['holiday_name'])?></li><?php endforeach;?></ul><?php if(!$holidays):?><p class="text-muted">No upcoming holidays.</p><?php endif;?></div></div><div class="card"><div class="card-header bg-primary text-white">Homework</div><div class="card-body"><?php foreach($homework as $x):?><article class="border-bottom pb-2 mb-2"><strong><?=portal_student_e($x['title'])?></strong> <span class="badge badge-warning"><?=portal_student_e($x['due_date'])?></span><p><?=nl2br(portal_student_e($x['description']))?></p></article><?php endforeach;?><?php if(!$homework):?><p class="text-muted">No homework posted.</p><?php endif;?></div></div></div></div>
</div></section></div><?php include '../../includes/footer.php'; ?>
